// spec: specs/seo-robots-sitemap.md (2.1–2.3) · кейсы: .qa/tests/seo-robots-sitemap/SITEMAP-01..03
// seed: tests/seed.spec.ts (гость) · прод: только чтение; в браузере все не-GET запросы обрываются.
import { test, expect } from '@playwright/test';
import { ORIGIN, BLOCKED_PATHS, readSitemap, robotsMeta, indexMeta } from './robots-sitemap.helpers';

test.use({ serviceWorkers: 'block' });

const MISSING_ID = '00000000-0000-0000-0000-000000000000';

test.describe('sitemap.xml', () => {
  test('sitemap.xml: urlset, все URL https://www., без дублей и приватных путей, главные публичные, объявления и категории #d777c9 @desktop @prod-safe', async ({ request }) => {
    const sm = await readSitemap(request);
    expect(sm.ctype, 'content-type').toContain('xml');
    expect(sm.body, 'urlset').toContain('<urlset');
    expect(sm.locs.length, 'URL в sitemap').toBeGreaterThan(0);

    expect(sm.locs.filter((l) => !l.startsWith(`${ORIGIN}/`)), 'URL не на https://www.').toEqual([]);
    expect(sm.locs.filter((l, i) => sm.locs.indexOf(l) !== i), 'дубли').toEqual([]);

    const paths = sm.locs.map((l) => { const u = new URL(l); return u.pathname + u.search; });
    expect(paths.filter((p) => BLOCKED_PATHS.some((b) => p.startsWith(b))), 'приватные/служебные пути в sitemap').toEqual([]);

    const pathnames = new Set(sm.locs.map((l) => new URL(l).pathname));
    for (const p of ['/', '/search', '/packages', '/calculator', '/buyerlistings']) expect(pathnames.has(p), `в sitemap есть ${p}`).toBe(true);

    expect(sm.listingIds.length, '≥ 1 /businessdetail?id=').toBeGreaterThan(0);
    const cats = sm.locs.map((l) => new URL(l)).filter((u) => u.pathname === '/search' && (u.searchParams.get('category') ?? '') !== '');
    expect(cats.length, '≥ 1 /search?category=').toBeGreaterThan(0);
  });

  test('Объявлений в sitemap столько же, сколько «נמצאו N» на /search; карточки сырого /search — из sitemap #d777c9 @desktop @prod-safe', async ({ page, request }) => {
    const sm = await readSitemap(request);
    const ids = new Set(sm.listingIds);
    expect(ids.size, 'объявления в sitemap').toBeGreaterThan(0);

    await page.route('**/*', (route) => (route.request().method() === 'GET' ? route.continue() : route.abort()));
    await page.goto('/search');
    const found = page.getByText(/נמצאו\s+[\d,]+/).first();
    await expect(found).toBeVisible({ timeout: 30_000 });
    await expect
      .poll(async () => Number(((await found.innerText()).match(/נמצאו\s+([\d,]+)/)?.[1] ?? '-1').replace(/,/g, '')), {
        message: '«נמצאו N» = число объявлений в sitemap',
        timeout: 30_000,
      })
      .toBe(ids.size);

    const raw = await (await request.get('/search')).text();
    const rawIds = [...new Set([...raw.matchAll(/\/businessdetail\?id=([0-9a-f-]{36})/gi)].map((m) => m[1]))];
    expect(rawIds.length, 'карточки в сыром /search').toBeGreaterThan(0);
    expect(rawIds.filter((id) => !ids.has(id)), 'id сырого /search, которых нет в sitemap').toEqual([]);
  });

  test('Несуществующее объявление: нет в sitemap, отдаёт noindex #d777c9 @desktop @prod-safe', async ({ request }) => {
    const sm = await readSitemap(request);
    expect(sm.listingIds, 'несуществующего id нет в sitemap').not.toContain(MISSING_ID);

    const res = await request.get(`/businessdetail?id=${MISSING_ID}`);
    expect([200, 404], 'статус').toContain(res.status());
    const header = res.headers()['x-robots-tag'] ?? '';
    const meta = robotsMeta(await res.text());
    expect(/noindex/i.test(header) || meta.some((m) => /noindex/i.test(m)), `noindex (X-Robots-Tag «${header}», meta ${JSON.stringify(meta)})`).toBe(true);
    expect(indexMeta(meta), 'нет meta «index» без noindex').toBe(false);
  });
});
